/* Reuse authored Arabic fields across every loaded game bank and story dataset.
   This is data-driven: adding an *_ar field automatically makes its English pair translatable. */
(function registerAuthoredArabicPairs(){
  const phrases=window.EPIPHANY_AR_TRANSLATION_PHRASES;
  const norm=value=>String(value||'').toLowerCase().replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/[.!?…,:;]+$/,'').replace(/\s+/g,' ').trim();
  const put=(en,ar)=>{if(typeof en==='string'&&en.trim()&&typeof ar==='string'&&ar.trim()&&/[\u0600-\u06FF]/.test(ar))phrases[norm(en)]=ar;};
  const seen=new Set();
  function visit(value){
    if(!value||typeof value!=='object'||seen.has(value))return;
    seen.add(value);
    if(Array.isArray(value)){value.forEach(visit);return;}
    for(const key of Object.keys(value)){
      if(key.endsWith('_ar')){
        const base=key==='why_ar'?'why_en':key.slice(0,-3), en=value[base], ar=value[key];
        if(typeof en==='string'&&typeof ar==='string')put(en,ar);
        if(Array.isArray(en)&&Array.isArray(ar))en.forEach((item,index)=>put(item,ar[index]));
      }
    }
    if(typeof value.en==='string'&&typeof value.ar==='string')put(value.en,value.ar);
    // Several content banks use a plain "ar" field beside a differently named English field.
    // Register these pairs explicitly so story pages and prompts receive exact translations too.
    if(typeof value.text==='string'&&typeof value.ar==='string')put(value.text,value.ar);
    if(typeof value.prompt==='string'&&typeof value.prompt_ar==='string')put(value.prompt,value.prompt_ar);
    if(typeof value.instruction==='string'&&typeof value.instruction_ar==='string')put(value.instruction,value.instruction_ar);
    if(typeof value.explain==='string'&&typeof value.ar==='string'&&value.ar.trim()&&!value.explain_ar)put(value.explain,value.ar);
    Object.values(value).forEach(visit);
  }
  const sources=[];
  // Include every first-party lesson/content bank that may carry authored *_ar fields.
  // Keep the explicit list safe: never traverse the browser's window/document object graph.
  if(typeof GAMES!=='undefined')sources.push(GAMES);
  if(typeof LEVELS!=='undefined')sources.push(LEVELS);
  if(typeof AR_EXPLANATIONS!=='undefined')sources.push(AR_EXPLANATIONS);
  if(typeof MISTAKE_QUESTIONS!=='undefined')sources.push(MISTAKE_QUESTIONS);
  if(typeof SPOT_QUESTIONS!=='undefined')sources.push(SPOT_QUESTIONS);
  if(typeof TYPING_QUESTIONS!=='undefined')sources.push(TYPING_QUESTIONS);
  if(typeof STORIES!=='undefined')sources.push(STORIES);
  if(typeof WORLD_MAP!=='undefined')sources.push(WORLD_MAP);
  if(typeof WORLD_TASKS!=='undefined')sources.push(WORLD_TASKS);
  if(typeof WORLD_QUESTIONS!=='undefined')sources.push(WORLD_QUESTIONS);
  if(typeof WOTD_WORDS!=='undefined')sources.push(WOTD_WORDS);
  if(typeof AHA_NOTES!=='undefined')sources.push(AHA_NOTES);
  if(typeof MINI_GAMES!=='undefined')sources.push(MINI_GAMES);
  if(typeof MINIGAMES!=='undefined')sources.push(MINIGAMES);
  if(typeof DIRECTIONS_DATA!=='undefined')sources.push(DIRECTIONS_DATA);
  if(typeof EPIPHANY_EXPANSION!=='undefined')sources.push(EPIPHANY_EXPANSION);
  sources.forEach(visit);
})();


